import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/data/app.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp REAL,
        action TEXT,
        details TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, password_hash, role, api_key) VALUES ('admin', 'admin@corp.internal', 'pbkdf2:sha256:260000$salt$hash', 'superadmin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (username, email, password_hash, role, api_key) VALUES ('svc_billing', 'billing@corp.internal', 'pbkdf2:sha256:260000$salt2$hash2', 'service', 'sk-billing-1a2b3c4d')")
    db.commit()
    db.close()

@app.before_request
def verify_request_signature():
    # Optional HMAC verification - only enforced if X-Signature header present
    sig = request.headers.get('X-Signature')
    if sig and HMAC_SECRET != 'default-dev-key':
        timestamp = request.headers.get('X-Timestamp', '')
        payload = f"{request.method}{request.path}{timestamp}".encode()
        expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return jsonify({"error": "invalid signature"}), 403

@app.route('/api/users/lookup', methods=['GET'])
def user_lookup():
    """Look up user by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Whitelist allowed fields to prevent arbitrary column access
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({"error": "field not allowed"}), 400

    # Build query with field from whitelist (safe) but value is user-controlled
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [{"id": r["id"], "username": r["username"], "email": r["email"], "role": r["role"]} for r in results]
        return jsonify({"users": users, "count": len(users)})
    except Exception as e:
        db.execute("INSERT INTO audit_log (timestamp, action, details) VALUES (?, ?, ?)",
                   (time.time(), 'query_error', str(e)))
        db.commit()
        return jsonify({"error": "query failed"}), 500

@app.route('/api/users/export', methods=['POST'])
def export_users():
    """Export user data as CSV. Requires role filter."""
    data = request.get_json(force=True)
    role_filter = data.get('role', 'user')
    format_type = data.get('format', 'json')

    query = f"SELECT id, username, email, role FROM users WHERE role = '{role_filter}'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        if format_type == 'csv':
            lines = ['id,username,email,role']
            for r in results:
                lines.append(f"{r['id']},{r['username']},{r['email']},{r['role']}")
            return '\n'.join(lines), 200, {'Content-Type': 'text/csv'}
        else:
            users = [{"id": r["id"], "username": r["username"], "email": r["email"], "role": r["role"]} for r in results]
            return jsonify({"users": users})
    except Exception as e:
        return jsonify({"error": "export failed"}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.4.1"})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
